fn original_android_render_options_and_token_reference_conversion(){let root=std::path::Path::new(env!("CARGO_MANIFEST_DIR"));let p=root.join("rewrite-review/milestones/m4-edit-save/evidence/name-render-dependencies-r0b52");let input:Value=serde_json::from_slice(&std::fs::read(p.join("inputs.json")).unwrap()).unwrap();let java:Value=serde_json::from_slice(&std::fs::read(p.join("java.json")).unwrap()).unwrap();let actual=json!({"options":options(),"cases":input["cases"].as_array().unwrap().iter().map(convert).collect::<Vec<_>>(),"cache":cache()});std::fs::write(p.join("rust.json"),serde_json::to_vec_pretty(&actual).unwrap()).unwrap();fn compare(a:&Value,b:&Value,path:&str){match(a,b){(Value::Object(x),Value::Object(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(k,v)in x{compare(v,y.get(k).unwrap(),&format!("{path}.{k}"));}},(Value::Array(x),Value::Array(y))=>{assert_eq!(x.len(),y.len(),"{path}");for(i,(a,b))in x.iter().zip(y).enumerate(){compare(a,b,&format!("{path}[{i}]"));}},_=>assert_eq!(a,b,"{path}")}}compare(&actual,&java,"root");}
